import XCTest

class ElementTests: XCTestCase {
    var app: XCUIApplication!

    override func setUp() {
        super.setUp()
        continueAfterFailure = false

        // Use the already-running Element app
        app = XCUIApplication(bundleIdentifier: "im.vector.app")
    }

    func testNavigateToBookClubAndReply() {
        // Wait for the app to be ready
        let searchField = app.otherElements["Search"]
        XCTAssertTrue(searchField.waitForExistence(timeout: 5), "Search field should exist")

        // Take a screenshot to see the current state
        XCTAttachment(screenshot: XCUIScreen.main.screenshot()).lifetime = .keepAlways

        // Try to find and tap the Book Club room
        let bookClubElements = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'Book Club'"))
        if bookClubElements.count > 0 {
            let bookClub = bookClubElements.element(boundBy: 0)
            bookClub.tap()
            sleep(1)
        } else {
            XCTFail("Book Club room not found")
        }

        // Find a message to reply to
        let messages = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'Dave'"))
        if messages.count > 0 {
            messages.element(boundBy: 0).tap()
            sleep(1)
        }

        // Find the reply/edit button or message input
        let replyButton = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Reply'")).firstMatch
        if replyButton.exists {
            replyButton.tap()
        }

        // Find the message input field and type the reply
        let messageFields = app.textFields.matching(NSPredicate(format: "placeholder CONTAINS 'Message'"))
        if messageFields.count > 0 {
            let inputField = messageFields.element(boundBy: 0)
            inputField.tap()
            inputField.typeText("sounds good")

            // Send the message
            let sendButton = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Send'")).firstMatch
            if sendButton.exists {
                sendButton.tap()
            }
        }

        sleep(2)
        XCTAttachment(screenshot: XCUIScreen.main.screenshot()).lifetime = .keepAlways
    }
}
EOF

